<?php
if(PHP_SAPI!=='cli'||getenv('EL_PREPROD_LOCAL')!=='1')throw new RuntimeException('Local only');
$c=require '/srv/state/private/config.php';if(empty($c['local_test'])||!str_contains($c['dsn'],'host=127.0.0.1;dbname=el_test_destination_'))throw new RuntimeException('Wrong environment');
$p=new PDO($c['dsn'],$c['db_user'],$c['db_password'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);
require '/srv/portal/app/BusinessDirectorySelector.php';$s=new BusinessDirectorySelector($p);$report=['places'=>[],'errors'=>[]];
foreach(glob(__DIR__.'/places/*/manifest.draft.json') as $f){$slug=json_decode(file_get_contents($f),true)['destination']['slug'];$q=$p->prepare('SELECT id FROM destinations WHERE slug=?');$q->execute([$slug]);$id=(int)$q->fetchColumn();$q=$p->prepare('SELECT publication_status,COUNT(*) AS total FROM points_of_interest WHERE destination_id=? GROUP BY publication_status');$q->execute([$id]);$pois=$q->fetchAll();$q=$p->prepare('SELECT publication_status,COUNT(*) AS total FROM businesses WHERE destination_id=? GROUP BY publication_status');$q->execute([$id]);$businesses=$q->fetchAll();$row=['slug'=>$slug,'attractions'=>$pois,'businesses'=>$businesses,'locales'=>[]];foreach(['es','en','pt-BR'] as $loc){$cats=$s->categoriesForPlace($id,$loc);$bs=$s->businessesForPlace($id,$loc);$empty=[];foreach($cats as $cat)if(!array_filter($bs,fn($b)=>in_array($cat['code'],$b['category_codes'],true)))$empty[]=$cat['code'];$row['locales'][$loc]=['visible'=>count($bs),'categories'=>array_column($cats,'code'),'empty_categories'=>$empty];if($empty)$report['errors'][]=[$slug,$loc,$empty];}$report['places'][]=$row;}
file_put_contents(__DIR__.'/directory-audit.json',json_encode($report,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE));echo json_encode(['places'=>count($report['places']),'locale_checks'=>count($report['places'])*3,'errors'=>$report['errors']]);
